mapper.select:
SELECT

FROM user_coupon c JOIN coupon_template t ON t.id=c.template_id

ORDER BY c.created_at DESC,
  c.id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(CASE WHEN  THEN 1 END) available,
       COUNT(CASE WHEN NOT  THEN 1 END) unavailable
FROM user_coupon c WHERE c.user_id=#{actor}

SELECT

FROM user_coupon c JOIN coupon_template t ON t.id=c.template_id
WHERE c.user_id=#{actor}
  AND c.id=#{id}

  FOR UPDATE

SELECT coupon_template_id AS template_id, target_id AS factory_id FROM coupon_scope_target WHERE scope_type='factory' AND coupon_template_id IN
#{id}
ORDER BY coupon_template_id, target_id
